	OnApproval: func(a *sai.Approval) *sai.ApprovalAnswer {
		if a.IsLinkOnly {
			fmt.Println("Approve in a browser:", a.URL)
			return nil // a person answers it; keep waiting
		}
		if a.Type == "choice" {
			var selections [][]string
			for _, q := range a.Questions {
				first := q["options"].([]any)[0].(map[string]any)
				selections = append(selections, []string{first["value"].(string)})
			}
			return &sai.ApprovalAnswer{Response: "yes", Selections: selections}
		}
		return &sai.ApprovalAnswer{Response: "yes"}
	},
})
if err != nil {
	log.Fatal(err)
}
