job, err := client.Learn.Create(ctx, nil, &sai.LearnOptions{
	TaskTemplate:  "Open {{newsSite}}, find all {{topic}} news published today, write their headlines into Notepad, one per line, and save the file as {{fileName}}",
	Inputs:        map[string]any{"newsSite": "TechCrunch", "topic": "AI", "fileName": "techcrunch_headlines.txt"},
	Machine:       pc.ID,
	Criteria:      sai.CriteriaText("techcrunch_headlines.txt is saved and holds, one per line, the headlines of the AI articles TechCrunch published today"),
	MaxIterations: 3, // up to 3 code versions; 0 (the default) only writes the code
	Rollouts:      3, // each version must pass 3 runs in a row
	Reset: &sai.ResetAction{Code: `for (const t of await machine.browser.listTabs()) await machine.browser.closeTab(t.tabId)
for (const w of await machine.getWindow("Notepad")) await w.close()`},
	ContinueWithAgent: true, // after a failed run, the agent finishes the task and the repair learns from it
})
if err != nil {
	log.Fatal(err)
}
done, err := client.Learn.Wait(ctx, job.ID, nil) // can take an hour; a context deadline stops waiting
if err != nil {
	log.Fatal(err)
}
fmt.Printf("%s %s %+v\n", done.Status, done.StopReason, done.TestResult)
fmt.Println(done.Code) // the latest version
for _, it := range done.Iterations {
	var verdicts []string
	for _, r := range it.Rollouts {
		verdicts = append(verdicts, r.Verdict)
	}
	fmt.Println(it.Index, it.Changes, verdicts)
}

run, err := client.Learn.Rollout(ctx, job.ID, 1, 1) // what one run returned and logged, and its judgement
if err != nil {
	log.Fatal(err)
}
fmt.Println(run.Run)
if err := client.Learn.Cancel(ctx, job.ID); err != nil { // stops at once and keeps the last complete results
	log.Fatal(err)
}

